#!/usr/bin/env node
// Claude Code Stop hook — generated by KeelWright.
// When Claude finishes a turn that changed files, runs the project's `check` task (lint, format
// check, type check, unit tests, theme drift). If it fails, Claude is told why and continues to
// fix it (exit 2). It runs at most once per stop: when Claude is already continuing because of
// this hook, it lets it stop.
//
// The command comes from `check` in .claude/hooks/config.json:
//   { "run": ["uv", "run", "poe", "check"], "requires": ".venv", "label": "uv run poe check" }
// ("requires": a path that must exist first, e.g. installed dependencies). Without a config file
// it runs `npm run check` once node_modules exists.

import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const DEFAULT = { run: ['npm', 'run', 'check', '--silent'], requires: 'node_modules', label: 'npm run check' };

let input = {};
try {
  input = JSON.parse(readFileSync(0, 'utf8'));
} catch {
  // no input: treat as a normal stop
}
if (input.stop_hook_active) process.exit(0);

const root = process.env.CLAUDE_PROJECT_DIR ?? input.cwd ?? process.cwd();
let check = DEFAULT;
const configFile = join(root, '.claude/hooks/config.json');
if (existsSync(configFile)) {
  try {
    check = JSON.parse(readFileSync(configFile, 'utf8')).check ?? null;
  } catch {
    check = DEFAULT;
  }
}
if (!check || !Array.isArray(check.run) || !check.run.length) process.exit(0);
if (check.requires && !existsSync(join(root, check.requires))) process.exit(0);

const status = spawnSync('git', ['status', '--porcelain'], { cwd: root, encoding: 'utf8' });
if (status.status !== 0 || !status.stdout.trim()) process.exit(0); // not a repo, or nothing changed

const [cmd, ...args] = check.run;
const r = spawnSync(cmd, args, { cwd: root, encoding: 'utf8', timeout: 5 * 60_000 });
if (r.error) process.exit(0); // the task runner isn't installed
if (r.status !== 0) {
  const label = check.label ?? check.run.join(' ');
  const output = `${r.stdout ?? ''}\n${r.stderr ?? ''}`.trim().split('\n').slice(-40).join('\n');
  process.stderr.write(`${label} fails after these changes. Fix the cause (don't weaken or skip checks):\n${output}\n`);
  process.exit(2);
}
process.exit(0);
